#include <string>
#include <sstream>

std::string convertMarkdownToHtml(const std::string& markdown) {
    std::stringstream html;

    // Encabezados
    std::string header = "";
    for (char c : markdown) {
        if (c == '#') {
            html << "<h1>";
            header += '#';
            continue;
        }
        if (c == '\n' && !header.empty()) {
            html << "</" << header << ">\n<h" << (header.size() - 1) << ">";
            header = "";
            continue;
        }
        if (c == '>' && !header.empty()) {
            html << "</" << header << ">\n<h" << (header.size() + 1) << ">";
            header = ">";
            continue;
        }
        if (c == '|' && !header.empty()) {
            html << "</" << header << ">\n<p>";
            header = "";
            continue;
        }
        header += c;
    }
    if (!header.empty()) {
        html << "</" << header << ">";
        header = "";
    }

    // Texto en negrita
    std::string bold = "";
    bool in_code = false;
    for (char c : markdown) {
        if (c == '*' && bold.empty()) {
            html << "<strong>";
            bold = "*";
            continue;
        }
        if (c == '_' && bold.empty()) {
            html << "<strong>";
            bold = "_";
            continue;
        }
        if (c == '`' && !in_code) {
            html << "<code>";
            in_code = true;
            continue;
        }
        if (c == '`' && in_code) {
            html << "</code>";
            in_code = false;
            continue;
        }
        html << c;
        bold = "";
        in_code = false;
    }
    if (!bold.empty()) {
        html << "</strong>";
    }

    // Enlaces
    std::string link = "";
    std::string title;
    bool link_title = false;
    for (char c : markdown) {
        if (c == '[' && link.empty()) {
            html << "<a href=\"";
            continue;
        }
        if (c == ']' && link.empty()) {
            html << "</a>";
            continue;
        }
        if (c == '(' && !link_title) {
            html << "<a href=\"";
            link_title = true;
            continue;
        }
        if (c == ')' && link_title) {
            html << "</a>";
            link_title = false;
            continue;
        }
        if (c == '|' && !link_title) {
            html << "</a><a href=\"";
            link_title = true;
            continue;
        }
        if (c == '|' && link_title) {
            html << "</a>";
            link_title = false;
            continue;
        }
        if (link_title) {
            title += c;
            continue;
        }
        if (c == '(' && link_title) {
            html << title << "(";
            title = "";
            continue;
        }
        if (c == ')' && link_title) {
            html << title << ")";
            title = "";
            continue;
        }
        if (c == '|' && link_title) {
            html << title << "|";
            title = "";
            continue;
        }
        if (c == '](' && link_title) {
            html << title << "(https://";
            title = "";
            continue;
        }
        if (c == '|](' && link_title) {
            html << title << "|(https://";
            title = "";
            continue;
        }
        html << c;
        link_title = false;
    }
    if (!link.empty()) {
        html << "</a>";
    }

    // Código fuente
    std::string pre = "";
    for (char c : markdown) {
        if (c == '`') {
            if (pre.empty()) {
                html << "<pre>";
                pre = "`";
                continue;
            } else {
                html << "</pre>";
                pre = "";
                continue;
            }
        }
        html << c;
        pre = "";
    }

    // Citas
    std::string quote = "";
    for (char c : markdown) {
        if (c == '>' && quote.empty()) {
            html << "<blockquote>";
            quote = ">";
            continue;
        }
        if (c == quote) {
            html << "</blockquote>";
            quote = "";
            continue;
        }
        html << c;
        quote = "";
    }

    // Listas
    std::string bullet = "";
    std::string number = "";
    for (char c : markdown) {
        if (c == '*' || c == '+' || c == '-') && bullet.empty()) {
            html << "<ul>";
            bullet = c;
            continue;
        }
        if (c == '\n' && !bullet.empty()) {
            html << "</" << bullet << ">\n";
            bullet = "";
            continue;
        }
        if ((c == '*' || c == '+' || c == '-') && bullet.empty()) {
            html << "<ol start=\"1\">";
            number += c;
            continue;
        }
        if (c == '\n' && !number.empty()) {
            html << "</" << number << ">\n";
            number = "";
            continue;
        }
        if (c == number.back()) {
            number.pop_back();
            html << "<li>";
            continue;
        }
        html << "<li>" << c;
    }
    if (!bullet.empty()) {
        html << "</ul>";
    }
    if (!number.empty()) {
        html << "</ol>";
    }

    // Lineas horizontales
    std::string hr = "";
    for (char c : markdown) {
        if (c == '-' || c == '*' || c == '_') {
            if (hr.empty()) {
                html << "<hr>";
                hr = c;
                continue;
            } else if (hr == '-' && c == '*' && (markdown.find_last_not_of(" *") == std::string::npos || markdown.back() != '*')) {
                html << "<hr/>";
                hr = "";
                continue;
            }
        }
        hr += c;
    }

    // Retornamos el contenido del stringstream como std::string.
    return html.str();
}
