Aquí te presento una función en JavaScript que verifica si algún número de un array de 5 números es primo y, si es así, imprime el número en la consola:

```javascript
function esPrimo(arr) {
  // Verificamos que el array tenga exactamente 5 números
  if (arr.length !== 5) {
    throw new Error('La entrada debe ser un array de 5 números');
  }

  // Recorremos el array para verificar si algún número es primo
  for (let num of arr) {
    if (esPrimoValido(num)) {
      console.log(num);
    }
  }

  function esPrimoValido(num) {
    // Evitamos valores no numéricos y cero
    if (typeof num !== 'number' || num === 0) return false;

    // Evitamos 1, ya que por definición 1 no es primo
    if (num === 1) return false;

    // Comprobamos si el número es divisible por cualquier número entre 2 y él mismo, exceptuando 2 y él mismo
    for (let I = 2; I < num; i++) {
      if (num % I === 0) {
        return false;
      }
    }

    // Si no encontramos divisores, el número es primo
    return true;
  }
}
```

Para usar esta función, simplemente pasa un array de 5 números como argumento:

```javascript
const numeros = [2, 3, 7, 11, 17];
esPrimo(numeros);
// Output: 2 3 7 11 17 (imprimidos en la consola)
```

Si pasas un array con menos de 5 números o algún valor no numérico, se lanzará un error.

